// In Application:  public interface IReceiptNumberGenerator { Task<string> NextAsync(DateTime utcNow, CancellationToken ct); }
// In AppDbContext.OnModelCreating:  builder.HasSequence<long>("ReceiptNumbers", schema: "dbo").StartsAt(1).IncrementsBy(1);
// Then: dotnet ef migrations add AddReceiptNumberSequence
internal sealed class SqlReceiptNumberGenerator(AppDbContext db) : IReceiptNumberGenerator
{
    public async Task<string> NextAsync(DateTime utcNow, CancellationToken ct)
    {
        // ToListAsync rather than SingleAsync: the latter wraps the SQL in a subquery,
        // and SQL Server forbids NEXT VALUE FOR inside derived tables
        var values = await db.Database
            .SqlQuery<long>($"SELECT NEXT VALUE FOR dbo.ReceiptNumbers AS [Value]")
            .ToListAsync(ct);

        return string.Create(CultureInfo.InvariantCulture, $"DN-{utcNow.Year}-{values[0]:D6}");
    }
}

